    static class PrefixProductSequence {
        public int[] div;
        public boolean[] forbidden;
        public ArrayList<Long> ans;
        public int n;
        public int m;

        public void solve(int testNumber, InputReader in, OutputWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            forbidden = new boolean[m + 1];
            for (int i = 0; i < n; i++) {
                forbidden[in.nextInt()] = true;
            }
            int[] add = new int[m + 1];
            for (int i = 0; i < m; i++) {
                if (!forbidden[i]) {
                    int g = Utils.gcd(i, m);
                    add[m / g]++;
                }
            }
            int[] arr = new int[m + 1];
            div = new int[m + 1];
            Arrays.fill(arr, 1);
            Arrays.setAll(div, x -> x);
            for (int i = 2; i <= m; i++) {
                arr[i] += add[i];
                for (int j = i + i; j <= m; j += i) {
                    if (arr[i] > arr[j]) {
                        arr[j] = arr[i];
                        div[j] = j / i;
                    }
                }
            }

            ans = new ArrayList<>();
            solve(1, 1);
            out.println(ans.size());
            boolean first = true;
            for (long x : ans) {
                if (!first) out.print(" ");
                out.print(x);
                first = false;
            }
            out.println();
        }

        public void solve(int cmult, long mm) {
            if (cmult == m) {
                if (!forbidden[0]) {
                    ans.add(0L);
                }
                return;
            }
            int prev = 1;
            boolean has = false;
            for (int i = 1; i < m / cmult; i++) {
                if (!forbidden[i * cmult] && Utils.gcd(m / cmult, i) == 1) {
                    long x = Utils.inv(prev, m / cmult) * i % m;
                    if (!has) {
                        has = true;
                        x = x * mm % m;
                    }
                    ans.add(x);
                    prev = i;
                }
            }
            long nmm = Utils.inv(prev, m / cmult) * div[m / cmult] % m;
            if (!has) nmm = nmm * mm % m;
            solve(cmult * div[m / cmult], nmm);
        }

    }

