            return add;
        }

        static class Node {
            public static int cgen;
            public int x;
            public int y;
            public int label;
            public int gen;
            public int nleaves;
            public int which;
            public ForgottenTree.Node lchild;
            public ForgottenTree.Node rchild;
            public ForgottenTree.Node par;

            public Node(int label) {
                this.lchild = null;
                this.rchild = null;
                this.par = null;
                this.which = 0;
                this.label = label;
                this.gen = 0;
                this.nleaves = 1;
            }

            public boolean active() {
                return gen < cgen;
            }

            public void disable() {
                this.gen = cgen;
            }

            public boolean isLeaf() {
                return lchild == null || (!lchild.active() && !rchild.active());
            }

            public void setChild(int which, ForgottenTree.Node x) {
                if (which == 0) {
                    this.lchild = x;
                } else {
                    this.rchild = x;
                }
                x.par = this;
                x.which = which;
            }

            public void dfs() {
                if (isLeaf()) {
                    this.nleaves = 1;
                    return;
                }

                this.nleaves = 0;
                if (lchild.active()) {
                    lchild.dfs();
                    this.nleaves += lchild.nleaves;
                }
                if (rchild.active()) {
                    rchild.dfs();
                    this.nleaves += rchild.nleaves;
                }
            }

            public void getLeaves() {
                if (lchild == null) {
                    this.x = this.y = label;
                    return;
                }
                lchild.getLeaves();
                rchild.getLeaves();
                this.x = lchild.x;
                this.y = rchild.x;
            }

        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (this.numChars == -1) {
                throw new InputMismatchException();
            } else {
                if (this.curChar >= this.numChars) {
                    this.curChar = 0;

                    try {
                        this.numChars = this.stream.read(this.buf);
                    } catch (IOException var2) {
                        throw new InputMismatchException();
                    }

                    if (this.numChars <= 0) {
                        return -1;
                    }
                }

                return this.buf[this.curChar++];
            }
        }

        public int nextInt() {
            int c;
            for (c = this.read(); isSpaceChar(c); c = this.read()) {
                ;
            }

            byte sgn = 1;
            if (c == 45) {
                sgn = -1;
                c = this.read();
            }

            int res = 0;

            while (c >= 48 && c <= 57) {
                res *= 10;
                res += c - 48;
                c = this.read();
                if (isSpaceChar(c)) {
                    return res * sgn;
                }
            }

            throw new InputMismatchException();
        }

        public String next() {
            int c;
            while (isSpaceChar(c = this.read())) {
                ;
            }

            StringBuilder result = new StringBuilder();
            result.appendCodePoint(c);

            while (!isSpaceChar(c = this.read())) {
                result.appendCodePoint(c);
            }

            return result.toString();
        }

        public static boolean isSpaceChar(int c) {
            return c == 32 || c == 10 || c == 13 || c == 9 || c == -1;
        }

    }

